//! Generated by `gpuicn init` and `gpuicn theme`; change the theme with `gpuicn theme set` or
//! `gpuicn theme import`, or edit `assets/theme.css` and keep this file.

use super::theme::{Appearance, ThemeMode, UiTheme};

/// The app's shadcn theme CSS (`:root` is light, `.dark` is dark).
pub const CSS: &str = include_str!("../../assets/theme.css");
/// The appearance gpuicn.toml selects; `System` follows the OS.
pub const APPEARANCE: Appearance = Appearance::System;

/// The light theme from `assets/theme.css`.
pub fn light() -> UiTheme {
    UiTheme::from_shadcn_css(CSS, ThemeMode::Light).expect("assets/theme.css parses")
}

/// The dark theme from `assets/theme.css`.
pub fn dark() -> UiTheme {
    UiTheme::from_shadcn_css(CSS, ThemeMode::Dark).expect("assets/theme.css parses")
}
